        onComplete: () => {
          // Animate text within items with more varied timing
          categoryItems.forEach((item, index) => {
            setTimeout(() => {
              const link = item.querySelector('a');
              if (link) {
                animateText(link, { 
                  staggerRange: [0.01, 0.12]  // Wider range
                });
              }

              const count = item.querySelector('.count');
              if (count) {
                setTimeout(() => {
                  animateText(count, { 
                    staggerRange: [0.01, 0.08]  // More variation
                  });
                }, getRandomValue(20, 60)); // Varied delay for count animation
              }
            }, index * getRandomValue(30, 60)); // More varied delay between items
          });
        }
      }
    );
  }
};

// Create a named export object
const textAnimator = { animateText, animateTextInContainer, animateAllContent };

export default textAnimator;
